package com.ecommerce.product; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ProductRepository extends JpaRepository<Product,UUID>{Page<Product> findByStatus(Product.Status status,Pageable pageable); Page<Product> findByNameContainingIgnoreCaseAndStatus(String name,Product.Status status,Pageable pageable); List<Product> findBySellerIdOrderByCreatedAtDesc(UUID sellerId);}
